 const auto fixture=std::filesystem::path(argv[1])/"fixtures/library/authored-three-chapters.epub";const auto source=bytes(fixture);const auto hash=QString::fromLatin1(QCryptographicHash::hash(source,QCryptographicHash::Sha256).toHex());QTemporaryDir temp;check(temp.isValid(),"annotation_private_fixture_root");std::filesystem::path libraryRoot=std::filesystem::path(temp.path().toStdString())/"library";library::Document book;
