 {const int b0=text.indexOf("Authored",last),b1=text.indexOf("fixture",b0)+7;check(b1>b0,"separate_epub_passage_available");auto second=selection(old,baseline,1,b0,b1);auto multi=anchor;QJsonArray segments;for(auto part:{anchor,second})segments.append(QJsonObject{{"start",part["start"]},{"end",part["end"]},{"excerpt",part["excerpt"]},{"prefix",part["prefix"]},{"suffix",part["suffix"]}});auto quads=anchor["quads"].toArray();for(auto q:second["quads"].toArray())quads.append(q);multi["segments"]=segments;multi["end"]=second["end"];multi["suffix"]=second["suffix"];multi["excerpt"]=anchor["excerpt"].toString()+"\n\n"+second["excerpt"].toString();multi["quads"]=quads;auto captured=ea::capture(old,baseline,multi);if(captured["status"]!="anchored")std::cerr<<QJsonDocument(captured).toJson(QJsonDocument::Compact).constData()<<'\n';check(captured["status"]=="anchored"&&captured["anchors"].toArray().size()==2,"separate_epub_passages_capture_exactly");auto same=ea::resolve(old,baseline,captured);check(same["status"]=="resolved"&&same["fragments"].toArray().size()==2,"separate_epub_passages_same_page_fragments");auto flowed=ea::resolve(next,target,captured);check(flowed["status"]=="resolved","separate_epub_passages_reflow");for(auto v:flowed["fragments"].toArray()){auto f=v.toObject(),actual=selection(next,target,f["page"].toInt(),f["first"].toInt(),f["last"].toInt());check(actual["quads"]==f["quads"]&&actual["excerpt"]==f["text"],"separate_epub_passage_geometry_matches_actual_source");}auto bad=multi;auto wrong=segments;auto part=wrong[0].toObject();part["quads"]=QJsonArray{};wrong[0]=part;bad["segments"]=wrong;check(ea::capture(old,baseline,bad)["status"]=="unresolved","segment_quad_duplication_schema_rejected");}
