 auto damaged=captured,sourceAnchor=captured["anchor"].toObject();sourceAnchor["chapterSourceSha256"]=QString(64,'f');damaged["anchor"]=sourceAnchor;check(ea::resolve(next,target,damaged)["status"]=="unresolved","annotation_chapter_fingerprint_rejected");
