 auto pageNote=anchor;for(auto key:{"start","end","prefix","suffix","quads"})pageNote.remove(key);pageNote["scope"]="page-location";pageNote["excerpt"]="";check(ea::capture(old,baseline,pageNote)["status"]=="anchored","page_location_note_uses_actual_original_top_word");
